const index = await readFile(join(OUT, "index.html"), "utf8");
const base = index.match(/<link rel="stylesheet" href="([^"]*)assets\\/styles\\.css"/)?.[1] ?? "/";

const seen = new Set(["index.html"]);
const queue = ["index.html"];
while (queue.length) {
  const current = queue.shift();
  const html = await readFile(join(OUT, current), "utf8");
  for (const m of html.matchAll(/href="([^"]+)"/g)) {
    const target = m[1];
    if (!target.startsWith(base)) continue;
    let local = decodeURIComponent(target.slice(base.length)) || "index.html";
    if (local.endsWith("/")) local += "index.html";
    if (!pages.some((p) => relative(OUT, p).replaceAll("\\\\", "/") === local)) continue;
    if (seen.has(local)) continue;
    seen.add(local);
    queue.push(local);
  }
}

for (const file of pages) {
  const rel = relative(OUT, file).replaceAll("\\\\", "/");
  if (rel === "404.html") continue;
  if (!seen.has(rel)) flag("index.html", `unreachable from the home page: ${rel}`);
}
'''
assert old in s
s = s.replace(old,new)
